{
  "root_causes": [
    {
      "service": "payment",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, count(*) AS n, min(value) AS uptime_min, max(value) AS uptime_max FROM abnormal_metrics_sum WHERE service_name='payment' AND metric='k8s.pod.uptime' GROUP BY 1 ORDER BY 1",
          "claim": "Payment pod jxhjm stops reporting and new pod cnpmj starts with uptime about 5s and reaches about 280s, so the instance was replaced at window start."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_span_kind k, span_name, round(duration/1e6,1) ms, attr_status_code st, strftime(time,'%H:%M:%S') t FROM abnormal_traces WHERE service_name='payment' ORDER BY time LIMIT 12",
          "claim": "Payment emits no spans from about 09:53:20 to 09:54:36, then resumes; the first Charge after the gap waits about 130s with an error."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind k, span_name, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, round(sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END)*1.0/count(*),3) err FROM abnormal_traces WHERE service_name='payment' AND attr_span_kind='Server' GROUP BY 1,2,3 UNION ALL SELECT service_name, attr_span_kind, span_name, round(quantile_cont(duration,0.95)/1e6,1), round(sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END)*1.0/count(*),3) FROM normal_traces WHERE service_name='payment' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "Payment Charge server p95 rose to about 71.6s in the abnormal window, versus about 1.5ms in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, round(duration/1e6,1) ms, attr_status_code st, strftime(time,'%H:%M:%S') t FROM abnormal_traces WHERE service_name='payment' AND span_name IN ('tcp.connect','grpc.flagd.evaluation.v1.Service/EventStream') ORDER BY time",
          "claim": "Payment's connections to flagd time out after about 130s with errors, in repeated tcp.connect attempts."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "payment",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind k, span_name, round(duration/1e6,1) ms, attr_status_code st FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='payment' AND attr_span_kind='Server' AND duration>1e9) AND service_name IN ('checkout','payment') ORDER BY service_name, time",
          "claim": "Checkout's PaymentService/Charge client span errors after about 130s, matching payment's slow Server Charge span in the same trace."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind k, span_name, count(*) n, round(max(duration/1e6),1) max_ms FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='checkout' AND duration>1e10) AND service_name IN ('frontend','frontend-proxy','checkout') GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "Traces with 130s checkout spans also contain frontend POST server spans of about 15s and frontend-proxy ingress spans."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind k, span_name, attr_http_response_status_code code, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_span_kind='Server' GROUP BY 1,2,3,4 ORDER BY 4",
          "claim": "Frontend-proxy ingress shows 500 and 504 responses for user requests in the abnormal window, all errors."
        }
      ]
    }
  ]
}
